def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, w))

    if m == n - 1:
        return ''

    # Kruskal's algorithm to find MST
    parent = list(range(n + 1))
    def uf_find(x):
        if parent[x] != x:
            parent[x] = uf_find(parent[x])
        return parent[x]

    rank = [0] * (n + 1)
    def uf_union(x, y):
        rootx, rooty = uf_find(x), uf_find(y)
        if rootx != rooty:
            if rank[rootx] < rank[rooty]:
                parent[rootx] = rooty
            elif rank[rootx] > rank[rooty]:
                parent[rooty] = rootx
            else:
                parent[rooty] = rootx
                rank[rootx] += 1
            return True
        return False

    # Sort edges by weight
    sorted_edges = sorted(edges, key=lambda x: x[2])

    mst_adj = [[] for _ in range(n + 1)]
    for u, v, w in sorted_edges:
        if uf_union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))

    # BFS to compute depths and immediate parents for binary lifting
    depth = [0] * (n + 1)
    up = [[-1] * 20 for _ in range(n + 1)]
    edge_weight = [0] * (n + 1)
    visited = [False] * (n + 1)

    queue = [1]
    visited[1] = True
    depth[1] = 0
    up[1][0] = 1

    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                up[v][0] = u
                edge_weight[v] = w
                queue.append(v)

    # Precompute binary lifting table
    LOG = 20
    for j in range(1, LOG):
        for i in range(1, n + 1):
            if up[i][j-1] != -1 and up[i][j-1] != i:
                up[i][j] = up[up[i][j-1]][j-1]
                edge_weight[i][j] = max(edge_weight[i][j-1], edge_weight[up[i][j-1]][j-1])

    def get_path_max(u, v):
        res = 0
        # Bring to same depth
        while depth[u] > depth[v]:
            diff = depth[u] - depth[v]
            for bit in range(LOG):
                if diff & (1 << bit):
                    res = max(res, edge_weight[u][bit])
                    u = up[u][bit]
        while depth[v] > depth[u]:
            diff = depth[v] - depth[u]
            for bit in range(LOG):
                if diff & (1 << bit):
                    res = max(res, edge_weight[v][bit])
                    v = up[v][bit]

        # Find path max to LCA
        for bit in range(LOG - 1, -1, -1):
            if up[u][bit] != up[v][bit]:
                res = max(res, edge_weight[u][bit], edge_weight[v][bit])
                u = up[u][bit]
                v = up[v][bit]

        # One more step to reach LCA
        res = max(res, edge_weight[u][0], edge_weight[v][0])
        return res

    results = []
    for u, v, w in edges:
        if not uf_union(u, v):
            mst_max = get_path_max(u, v)
            results.append(str(mst_max))

    return '\n'.join(results)

