    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        literals = parts[1:]

        for lit_idx in range(len(literals)):
            literal = literals[lit_idx]
            literal_pos = abs(literal)
            is_positive = literal > 0

            # Node for the literal itself
            if is_positive:
                lit_node = literal_pos
            else:
                lit_node = literal_pos + m

            # Node for the negation of the literal
            if is_positive:
                neg_lit_node = literal_pos + m
            else:
                neg_lit_node = literal_pos

            for other_idx in range(len(literals)):
                if lit_idx != other_idx:
                    other = literals[other_idx]
                    other_pos = abs(other)
                    is_other_positive = other > 0

                    if is_other_positive:
                        other_node = other_pos
                    else:
                        other_node = other_pos + m

                    # Add edge from negation to other literal
                    graph[neg_lit_node].append(other_node)

    # Tarjan's algorithm for SCC
    index_counter = [0]
    stack = []
    low = [-1] * (2 * m + 1)
    index = [-1] * (2 * m + 1)
    on_stack = [False] * (2 * m + 1)
    scc = [-1] * (2 * m + 1)

    def dfs(at):
        stack.append(at)
        index[at] = low[at] = index_counter[0]
        index_counter[0] += 1
        on_stack[at] = True

        for to in graph[at]:
            if index[to] == -1:
                dfs(to)
                low[at] = min(low[at], low[to])
            elif on_stack[to]:
                low[at] = min(low[at], index[to])

        if low[at] == index[at]:
            count = []
            while True:
                node = stack.pop()
                on_stack[node] = False
                scc[node] = index_counter[0]
                count.append(scc[node])
                if node == at:
                    break
            index_counter[0] += 1

    for i in range(1, 2 * m + 1):
        if index[i] == -1:
            dfs(i)

    # Check satisfiability: if x_i and ¬x_i in same SCC
    for i in range(1, m + 1):
        if scc[i] == scc[m + i]:
            return "NO\n"

    # Build satisfying assignment
    # Assign 0 to x_i if component of x_i < component of ¬x_i
    assignment = [''] * m
    for i in range(1, m + 1):
        if scc[i] < scc[m + i]:
            assignment[i - 1] = '1'
        else:
            assignment[i - 1] = '0'

    return "YES\n" + "".join(assignment)

