class Check:
    def __init__(self, a, n):
        # Precompute prefix alternating sums
        # P[i] = a[0] - a[1] + a[2] - a[3] + ... (up to index i)
        # With alternating signs

        self.P = [0] * n
        running = 0
        for i in range(n):
            if i % 2 == 0:
                running += a[i]
            else:
                running -= a[i]
            self.P[i] = running

        self.n = n
        self.result = "NO"

    def validate(self, a):
        """Check if array 'a' can have all stones removed."""
        running = 0
        for i in range(self.n - 1):
            if i % 2 == 0:
                running += a[i]
            else:
                running -= a[i]
            if running < 0:
                return False
        # Check if last element is 0 (meaning pile n will be empty)
        if running + a[-1] == 0:
            return True
        return False

    def try_swap(self, i):
        """Try swap at position i, return True if valid."""
        new_p = self.P[:]

        # Swap affects P[i] and P[i+1], and indirectly P[i+2...]
        # When we swap a[i] and a[i+1]:
        # - P[i] changes from a[i] - prev to a[i+1] - prev (if i even)
        # - The running sum from i+1 onwards changes

        delta = a[i + 1] - a[i] if i % 2 == 0 else -(a[i + 1] - a[i])

        # Recalculate running from i+1
        prev = 0
        for k in range(i + 1):
            if k == i:
                prev += a[i+1]  # New value at position i after swap
                if k % 2 == 0:
                    continue
            else:
                prev += a[k]
                if k % 2 == 1:
                    prev -= a[k]

        # Check remaining
        for k in range(i + 1, self.n - 1):
            if k % 2 == 0:
                prev += a[k]
            else:
                prev -= a[k]
            if prev < 0:
                return False

        # Check final element makes it zero
        prev += delta  # Account for the swap adjustment
        if prev == 0:
            return True
        return False

    def check(self):
        """Main logic to check if solution exists."""
        a = self.__dict__['array']

        # Try if already valid (no swap needed)
        if self.validate(a):
            self.result = "YES"
            return

        # Try each adjacent swap
        for i in range(self.n - 1):
            # Simulate swap and check
            temp_a = a[:]
            temp_a[i], temp_a[i+1] = temp_a[i+1], temp_a[i]

            if self.validate(temp_a):
                self.result = "YES"
                return

        self.result = "NO"


