    grid = [list(lines[i+1]) for i in range(n)]

    if n == 0 or m == 0:
        return "0"

    # Precompute row prefix XORs
    # row_prefix[i][j] = XOR sum of (1 << (ord(grid[i][k]) - ord('a'))) for k in 0..j-1
    row_prefix = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        for j in range(m):
            row_prefix[i][j+1] = row_prefix[i][j] ^ (1 << (ord(grid[i][j]) - ord('a')))

    # Precompute column prefix XORs
    # col_prefix[i][j] stores XOR sum of character bits in first i rows of column j
    col_prefix = [[0] * m for _ in range(n + 1)]
    for i in range(n):
        for j in range(m):
            col_prefix[i+1][j] = col_prefix[i][j] ^ (1 << (ord(grid[i][j]) - ord('a')))

    count = 0
    for i1 in range(n):
        for i2 in range(i1, n):
            for j1 in range(m):
                for j2 in range(j1, m):
                    # Check row condition: all rows in [i1, i2] restricted to cols [j1, j2]
                    valid_rows = True
                    for i in range(i1, i2+1):
                        x = row_prefix[i][j2+1] ^ row_prefix[i][j1]
                        # At most one bit set = at most one character with odd count = can be palindrome
                        if bin(x).count('1') > 1:
                            valid_rows = False
                            break
                    if not valid_rows:
                        continue

                    # Check column condition: all columns in [j1, j2] restricted to rows [i1, i2]
                    valid_cols = True
                    for j in range(j1, j2+1):
                        x = col_prefix[i2+1][j] ^ col_prefix[i1][j]
                        if bin(x).count('1') > 1:
                            valid_cols = False
                            break
                    if valid_cols:
                        count += 1

    return str(count)

