def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    adj = set()
    for i in range(m):
        p, q = map(int, lines[3 + i].split())
        adj.add((p, q))
        adj.add((q, p))

    source = 0
    sink = n + 1
    capacity = [[0] * (n + 2) for _ in range(n + 2)]
    flow = [[0] * (n + 2) for _ in range(n + 2)]

    # S -> cities with capacity = initial soldiers
    for i in range(n):
        capacity[source][i + 1] = a[i]

    # cities -> T with capacity = required soldiers
    for i in range(n):
        capacity[i + 1][sink] = b[i]

    INF = float('inf')
    # Connect adjacent cities bidirectionally
    for u, v in adj:
        capacity[u][v] = INF
        capacity[v][u] = INF

    # Self-loops (soldiers can stay)
    for i in range(1, n + 1):
        capacity[i][i] = INF

    total_flow = 0
    visited = [False] * (n + 2)
    parent = [-1] * (n + 2)

    while True:
        # BFS to find augmenting path
        visited = [False] * (n + 2)
        parent = [-1] * (n + 2)
        queue = deque([source])
        visited[source] = True

        found_path = False
        while queue:
            u = queue.popleft()
            if u == sink:
                found_path = True
                break

            for v in range(n + 2):
                if not visited[v] and capacity[u][v] - flow[u][v] > 0:
                    visited[v] = True
                    parent[v] = u
                    queue.append(v)

        if not found_path:
            break

        # Find bottleneck capacity
        bottleneck = INF
        v = sink
        while v != source:
            u = parent[v]
            bottleneck = min(bottleneck, capacity[u][v] - flow[u][v])
            v = u

        # Update residual graph
        v = sink
        while v != source:
            u = parent[v]
            flow[u][v] += bottleneck
            capacity[u][v] -= bottleneck
            capacity[v][u] += bottleneck
            v = u

        total_flow += bottleneck

    return "NO\n" if total_flow != sum(a) else "YES\n" + "\n".join(" ".join(map(str, flow[i + 1][1:n + 1])) for i in range(n))

