    # No visitors, Vasya goes first
    if n == 0:
        return str(ts)

    # Track service completion times for all visitors
    service_ends = []
    current_end = ts

    for arr_time in arrivals:
        # Visitor arrives, service starts when both visitor is present and rec is free
        start_time = max(arr_time, current_end)
        end_time = start_time + t
        service_ends.append(end_time)
        current_end = end_time

        # Early termination if service would extend beyond opening hours
        if end_time > tf:
            break

    # Find gap where service finished and next visitor hasn't arrived yet
    best_time = None

    for i in range(len(service_ends) - 1):
        gap_end = service_ends[i]  # When this visitor's service completes
        next_arrival = arrivals[i + 1]  # When next visitor arrives

        # Check if there's a gap (service ends before next visitor arrives)
        if gap_end < next_arrival and gap_end + t <= tf:
            # This gap is viable for Vasya
            if best_time is None:
                best_time = gap_end

    # If no valid gap found, return the latest safe time before a gap is lost
    if best_time is None:
