def solution(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    S = lines[1]
    T = lines[2]

    valid_positions = []

    # Check each possible starting position in S
    for i in range(n - m + 1):
        pair = {}
        valid = True

        for j in range(m):
            if S[i+j] == T[j]:
                continue  # Same character, no pair needed

            # Characters differ, so they must form a bidirectional pair (a<->b)

            # If a character was already paired, check for consistency
            if S[i+j] in pair and pair[S[i+j]] != T[j]:
                valid = False
                break

            if T[j] in pair and pair[T[j]] != S[i+j]:
                valid = False
                break

            # Record the ongoing pairing (bidirectional)
            pair[S[i+j]] = T[j]
            pair[T[j]] = S[i+j]

        if valid:
