def get_prime_factors(n):
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def check_order(b, n, p):
    """Check if b has order exactly n modulo p"""
    if pow(b, n, p) != 1:
        return False

    # Get prime factors of n
    temp = n
    prime_factors = set()
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            prime_factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        prime_factors.add(temp)

    # Check that b^(n/q) != 1 (mod p) for all prime factors q of n
    for q in prime_factors:
        if pow(b, n // q, p) == 1:
            return False

    return True

