def solution(input_str):
    """
    Solve the MST XOR problem.
    Input: string containing n, m and m lines of u, v, w
    Output: string containing the minimum ugliness (MST weight)
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse pre-assigned edges
    pre_assigned = []
    for i in range(1, m + 1):
        u, v, w = map(int, lines[i].split())
        pre_assigned.append((u, v, w))

    # Build complete graph with all edges
    # Use a set to track which edges are pre-assigned
    assigned_map = {}
    for u, v, w in pre_assigned:
        if u < v:
            assigned_map[(u, v)] = w
        else:
            assigned_map[(v, u)] = w

    # Create all edges in the complete graph
    all_edges = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i, j) in assigned_map:
                all_edges.append((i, j, assigned_map[(i, j)]))
            else:
                all_edges.append((i, j, 0))  # Unassigned edges get weight 0

    # Kruskal's algorithm to find MST
    all_edges.sort(key=lambda x: x[2])

    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_weight = 0
    edges_count = 0

    for u, v, w in all_edges:
        if union(u, v):
            mst_weight += w
            edges_count += 1
            if edges_count == n - 1:
                break

    # For the XOR constraint: with at least one unassigned edge,
    # we can adjust weights to satisfy XOR=0 without increasing MST

    return f"\n{mst_weight}\n"

