def inv_perm(P):
    """Compute inverse of permutation P (0-indexed values become 1-indexed output)"""
    n = len(P)
    inv = [0] * n
    for i in range(n):
        # P[i] is at position i, so in inverse: value (P[i]-1) maps to position (i+1)+1
        inv[P[i] - 1] = i + 1
    return inv

