    prob_ge = []
    for dp_j in dist:
        cumsum = 0.0
        ge = {}
        # P(C >= c) = sum from c to n
        for c in range(n, -1, -1):
            if cumsum < 1e-9:  # numerical stability
                continue
            ge = {**ge, c: cumsum + dp_j[c]}
        prob_ge.append(list(ge.values()))

    # Binary search for λ
