                obj = sum(prob_ge[j][-k-1:] or [0]) * (1 if k > 0 else 0) - k
                if obj > max_obj:
                    max_obj = obj
                    best_k = k
            k_sum += best_k

        return k_sum - n

    # Binary search for λ
    lo, hi = 0.0, 1.0
    for _ in range(60):
        mid = (lo + hi) / 2
        if check(mid) > 0:
