# Solution to Simon's house problem

def solution(input_str):
    """
    Solves Simon's problem of turning off all lights in an n×n grid
    while maintaining visibility to move and returning to start position.

    Args:
        input_str: Input string containing n, x0, y0, and grid configuration

    Returns:
        "YES\n<action_sequence>" if a solution exists, "NO" otherwise
    """

    # Parse input
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return "NO"

    try:
        n, x0, y0 = map(int, lines[0].split())
    except:
        return "NO"

    # Read grid
    grid = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, min(n, len(lines) - 1) + 1):
        try:
            parts = lines[i].split()
            for j in range(1, n + 1):
                if j - 1 < len(parts):
                    grid[i][j] = int(parts[j - 1])
        except:
            pass

    # Check for invalid input
    if n < 2:
        return "NO"

    # Find all positions with lights on
    lights_on = set()
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if grid[i][j] == 1:
                lights_on.add((i, j))

    # No lights to turn off? (should not happen per constraints)
    if not lights_on:
        return "NO"

    # Helper: Check if there's any light in direction (dx, dy) from (x,y)
    def has_light_in_direction(x, y, dx, dy):
        for k in range(1, n):
            nx, ny = x + dx * k, y + dy * k
            if nx < 1 or nx > n or ny < 1 or ny > n:
                break
            if grid[nx][ny] == 1:
                return True
        return False

    # Helper: Try to find a solution using depth-first search with pruning
    def solve(current_grid, max_depth):
        x, y = current_pos
        action_list = []
        path_keys = []

        if total_lights == 0:
            if x == x0 and y == y0:
                return "".join(action_list)
            return None

        # If path too long, prune
        if len(action_list) > max_depth:
            return None

        # Heuristic: always prefer turning off lights over toggling them back on
        # Try turning off current light if possible
        if (x, y) in lights_on:
            new_grid = [row[:] for row in current_grid]
            new_grid[x][y] = 0

            result = solve(new_grid, max_depth)
            if result:
                action_list.append('2')
                return result + "".join(action_list)

        # Try moving in all directions if visibility exists
        for dx, dy, direction in [(0, -1, 'L'), (0, 1, 'R'), (-1, 0, 'U'), (1, 0, 'D')]:
            if 1 <= x + dx <= n and 1 <= y + dy <= n:
                if has_light_in_direction(x, y, dx, dy):
                    result = solve(current_grid, max_depth)
                    if result:
                        action_list.append(direction)
                        return result + direction + "".join(action_list)

        # Try turning light ON if off (strategic move to maintain visibility)
        if grid[x][y] == 0:
            new_grid = [row[:] for row in current_grid]
            new_grid[x][y] = 1

            result = solve(new_grid, max_depth)
            if result:
                action_list.append('1')
                return result + '1' + "".join(action_list)

        return None

    # Initial setup for DFS
    current_pos = (x0, y0)
    total_lights = len(lights_on)
    max_actions = 3 * 10**6

    # Start search from initial position, avoiding modifying grid[same time moving]
    # We'll modify grid in place and backtrack

    def dfs(x, y, action_stack, grid_copy):
        nonlocal lights_on_set

        # Check if all lights turned off
        if not lights_on_set:
            if x == x0 and y == y0:
                return "".join(action_stack)
            else:
                return None

        # Limit action count
        if len(action_stack) >= max_actions:
            return None

        # Save state for backtracking
        old_grid = [[row[:] for row in grid_copy]]
        old_x = x
        old_y = y
        old_cell = grid_copy[x][y]
        old_light = (x, y) in lights_on_set

        # Strategy 1: Turn off current light
        if old_grid[0][x][y] == 1 and old_x == x and old_y == y:
            grid_copy[x][y] = 0
            if (x, y) not in lights_on_set:
                lights_on_set.discard((x, y))

            # Recurse
            result = dfs(x, y, action_stack + ['2'], grid_copy)
            if result:
                return result

            # Restore light
            grid_copy[x][y] = 1
            lights_on_set.add((x, y))

        # Strategy 2: Try moving in each direction
        for dx, dy, direction in [(0, -1, 'L'), (0, 1, 'R'), (-1, 0, 'U'), (1, 0, 'D')]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= n:
                if has_light_in_direction(x, y, dx, dy):
                    # Move before taking action
                    action_stack.append(direction)
                    if dfs(nx, ny, action_stack, grid_copy):
                        return action_stack[:]
                    action_stack.pop()

        # Strategy 3: Turn light ON if off (helps visibility)
        if grid_copy[x][y] == 0:
            if (x, y) in lights_on_set:
                pass  # Already counted
            else:
                light_added = True
                if (x, y) not in lights_on_set:
                    lights_on_set.add((x, y))

            # Recurse with light ON
            result = dfs(x, y, action_stack + ['1'], grid_copy)
            if result:
                return result

            # Restore to off
            lights_on_set.discard((x, y))

    # Start DFS
    lights_on_set = set(lights_on)
    grid_copy = grid

    result = dfs(x0, y0, [], grid_copy)

    if result:
        return f"YES\n{result}"
    else:
        return "NO"

