    while len(set(current_totals[1:])) != n:
        freq = defaultdict(int)
        for t in current_totals[1:]:
            freq[t] += 1

        # Find duplicates
        duplicates = {}
        for t, count in freq.items():
            if count > 1:
                duplicates[t] = True

        # Resolve by adding keepers
        if duplicates:
            # Add personal token to one vertex from each duplicate group
            for t in duplicates:
                for v in range(1, n + 1):
                    if not kept[v] and current_totals[v] == t:
                        current_totals[v] += 1
                        keeper_count += 1
                        keepers.append(v)
                        kept[v] = True
                        break

    # Format output
    result = f"{keeper_count}\n\n"
    for i, (u, v) in enumerate(edges):
