from math import gcd

def solution(s):
    parts = s.strip().split()
    x = int(parts[0])
    y = int(parts[1])

    # For x = 1, the answer is simply y (since gcd(1, y) = 1 always)
    if x == 1:
        return str(y)

    # For x > 1, simulate the counting process
    count = 0
    while y > 0:
        g = gcd(x, y)

        # If y is a multiple of gcd(x, y), we can batch multiple steps 
        # until y becomes non-divisible or we reach 0
        if y >= x * g or y % (x // g) == 0:
            # Calculate jumps
            if y == x:  # Edge case where y equals x exactly
                count += 1
                y = 0
            else:
                # Determine how many times we can subtract g
                # while keeping the gcd constant or until y < g
                c = y // g
                if c == 0:
                    c = 1
                # Batch operations to jump ends
                if y == x * c:
                    count += c
                    y = 0
                else:
                    y %= g
                    count += c
        else:
            y -= g
            count += 1

    return str(count)
